with j as (select * from jsonb_to_recordset($law7d0049$[{"code_id":"NK_RF","article_number":"105.13","version_date":"2000-07-31","article_text":"1. Метод распределения прибыли заключается в сопоставлении фактического распределения между сторонами сделки совокупной прибыли, полученной всеми сторонами этой сделки, с распределением прибыли между сторонами сопоставимых сделок.\n\n2. В случае, если стороны анализируемой сделки (группы однородных анализируемых сделок) одновременно являются сторонами однородных сделок с участием их взаимозависимых лиц и оценка цен по указанным однородным сделкам в целях налогообложения осуществляется в совокупности с анализируемой сделкой, для целей налогообложения совокупная прибыль по анализируемой сделке и указанным однородным сделкам подлежит распределению в порядке, аналогичном порядку распределения прибыли по анализируемой сделке.\n\n1) при невозможности использования методов, предусмотренных подпунктами 1 - 4 пункта 1 статьи 1057 настоящего Кодекса, и при наличии существенной взаимосвязи деятельности, осуществляемой сторонами анализируемой сделки (группы однородных анализируемых сделок);\n\n2) при наличии в собственности (пользовании) сторон анализируемой сделки прав на объекты нематериальных активов, оказывающие существенное влияние на уровень рентабельности (при отсутствии однородных сделок, предметом которых являются объекты нематериальных активов, совершенных с лицами, не являющимися взаимозависимыми), или в случае осуществления стороной анализируемой сделки контроля за использованием таких нематериальных активов. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n1) пропорционально вкладу в совокупную прибыль по анализируемой сделке функций, осуществляемых сторонами анализируемой сделки, используемых ими активов и принимаемых экономических (коммерческих) рисков;\n\n2) пропорционально распределению между сторонами анализируемой сделки доходности, полученной на вложенный капитал, используемый в анализируемой сделке;\n\n3) пропорционально распределению прибыли между сторонами сопоставимой сделки.\n\n1) на основе методов, указанных в подпунктах 1 - 4 пункта 1 статьи 1057 настоящего Кодекса, для каждого лица, являющегося стороной анализируемой сделки (группы однородных анализируемых сделок), на основании рыночного интервала цены для этой стороны определяется расчетная прибыль (убыток), которая (который) рассчитывается с учетом осуществляемых этим лицом функций, используемых им активов, принимаемых экономических и коммерческих рисков;\n\n2) остаточная прибыль (убыток) по анализируемой сделке определяется как разница между совокупной прибылью (убытком), полученной (полученным) по анализируемой сделке, и суммой расчетной прибыли (убытка) от продаж для всех сторон анализируемой сделки.\n\n1) размер затрат, понесенных лицом, являющимся стороной анализируемой сделки, на создание нематериальных активов, использование которых оказывает влияние на величину фактически полученной прибыли (убытка) по анализируемой сделке;\n\n2) характеристики персонала, занятого у лица, являющегося стороной анализируемой сделки, включая его численность и квалификацию (затраченное персоналом время, величина расходов на оплату труда), оказывающие влияние на величину фактически полученной прибыли (убытка) от продаж по анализируемой сделке;\n\n3) рыночная стоимость активов, находящихся в пользовании (распоряжении) лица, являющегося стороной анализируемой сделки, использование которых влияет на величину фактически полученной прибыли (убытка) от продаж по анализируемой сделке;\n\n4) другие показатели, отражающие взаимосвязь между осуществляемыми функциями, используемыми активами и принимаемыми экономическими (коммерческими) рисками и величиной фактически полученной прибыли (убытка) от продаж по анализируемой сделке.\n\n1) данные бухгалтерского учета сторон анализируемой сделки должны быть сопоставимы с данными бухгалтерского учета сторон сопоставимых сделок либо приведены к сопоставимому виду путем осуществления необходимых корректировок;\n\n2) совокупная рентабельность активов сторон анализируемой сделки не должна существенно отличаться от совокупной рентабельности активов сторон сопоставимых сделок либо должна быть приведена к сопоставимому виду путем осуществления необходимых корректировок.\n\nВ случае, если убыток, понесенный налогоплательщиком, являющимся стороной анализируемой сделки, превышает убыток, рассчитанный для этой стороны в соответствии с методом распределения прибыли, для целей налогообложения принимается убыток, рассчитанный для него в соответствии с методом распределения прибыли.\n\nНа основании сопоставления прибыли или убытка, учтенных в целях налогообложения в соответствии с\n\nнастоящим пунктом, с фактически полученной налогоплательщиком прибылью или фактически понесенным убытком осуществляется корректировка прибыли налогоплательщика в целях налогообложения налогом на прибыль организаций.","article_title":"Статья 105.13. Метод распределения прибыли","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"60d9bfb85c8d2a9840384db4c5574e10d68fb56c5d04ac463ac15f39da28cc5e"},{"code_id":"NK_RF","article_number":"105.14","version_date":"2000-07-31","article_text":"1. В целях настоящего Кодекса контролируемыми сделками признаются сделки между взаимозависимыми лицами (с учетом особенностей, предусмотренных настоящей статьей). К сделкам между взаимозависимыми лицами в целях настоящего Кодекса приравниваются следующие сделки:\n\n1) совокупность сделок по реализации (перепродаже) товаров (выполнению работ, оказанию услуг), совершаемых с участием (при посредничестве) лиц, не являющихся взаимозависимыми (с учетом особенностей, предусмотренных настоящим подпунктом). Указанная в настоящем подпункте совокупность сделок приравнивается к сделке между взаимозависимыми лицами, не принимая во внимание наличие третьих лиц, с участием (при посредничестве) которых совершается такая совокупность сделок, при условии, что такие третьи лица, не признаваемые взаимозависимыми и принимающие участие в указанной совокупности сделок:\n\nне выполняют в этой совокупности сделок никаких дополнительных функций, за исключением организации реализации (перепродажи) товаров (выполнения работ, оказания услуг) одним лицом другому лицу, признаваемому взаимозависимым с этим лицом;\n\nне принимают на себя никаких рисков и не используют никаких активов для организации реализации (перепродажи) товаров (выполнения работ, оказания услуг) одним лицом другому лицу, признаваемому взаимозависимым с этим лицом;\n\n2) сделки в области внешней торговли товарами, которые входят в состав одной или нескольких товарных групп, предусмотренных пунктом 5 настоящей статьи; (В редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\n3) сделки, одной из сторон которых является физическое лицо, организация или иностранная структура без образования юридического лица, если местом жительства, либо местом регистрации, либо местом налогового резидентства соответствующего лица, иностранной структуры без образования юридического лица или одного из участников (пайщиков, доверителей, иных лиц) либо иных бенефициаров, в интересах которых иностранная структура без образования юридического лица осуществляет свою деятельность, является государство или территория, включенные в утверждаемый Министерством финансов Российской Федерации перечень государств и территорий, предоставляющих льготный налоговый режим налогообложения и (или) не предусматривающих раскрытия и предоставления информации при проведении финансовых операций (офшорные зоны). В целях настоящего подпункта, если деятельность российской организации образует постоянное представительство в государстве или на территории, включенных в перечень, указанный в настоящем подпункте, и анализируемая сделка связана с этой деятельностью, в части этой анализируемой сделки такая организация рассматривается как лицо, местом регистрации которого является государство или территория, включенные в указанный перечень. (В редакции  федеральных законов от 27.11.2023 № 539-ФЗ, от 19.12.2023 № 595-ФЗ)\n\n1) стороны сделки применяют разные ставки по налогу на прибыль организаций (за исключением ставок, предусмотренных пунктами 2 - 4 статьи 284 настоящего Кодекса) к прибыли от деятельности, в рамках которой заключена указанная сделка; (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n2) одна из сторон сделки является налогоплательщиком налога на добычу полезных ископаемых, исчисляемого по налоговой ставке, установленной в процентах, и предметом сделки является добытое полезное ископаемое, признаваемое для указанной стороны сделки объектом налогообложения налогом на добычу полезных ископаемых, при добыче которого налогообложение производится по налоговой ставке, установленной в процентах;\n\n3) хотя бы одна из сторон сделки является налогоплательщиком, применяющим систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог) (если соответствующая сделка заключена в рамках такой деятельности), при этом в числе других лиц, являющихся сторонами указанной сделки, есть лицо, не применяющее указанный специальный налоговый режим; (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\n4) одна из сторон сделки освобождена от обязанностей налогоплательщика налога на прибыль организаций; (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n5) (Подпункт утратил силу - Федеральный закон от 03.08.2018 № 302-ФЗ)\n\n6) сделка удовлетворяет одновременно следующим условиям:\n\nодна из сторон сделки является налогоплательщиком, указанным в пункте 1 статьи 2752 настоящего Кодекса, и учитывает доходы (расходы) по такой сделке при определении налоговой базы по налогу на прибыль организаций в соответствии со статьей 2752 настоящего Кодекса;\n\nлюбая другая сторона сделки не является налогоплательщиком, указанным в пункте 1 статьи 2752 настоящего Кодекса, либо является налогоплательщиком, указанным в пункте 1 статьи 2752 настоящего Кодекса, но не учитывает доходы (расходы) по такой сделке при определении налоговой базы по налогу на прибыль организаций в соответствии со статьей 2752 настоящего Кодекса;\n\n(Дополнение подпунктом - Федеральный закон от 30.09.2013 № 268-ФЗ)\n\n7) (Дополнение подпунктом - Федеральный закон от 30.09.2013 № 267-ФЗ) (Утратил силу - Федеральный закон от 03.08.2018 № 302-ФЗ)\n\n8) хотя бы одна из сторон сделки является исследовательским корпоративным центром, указанным в Федеральном законе \"Об инновационном центре \"Сколково\" (далее в настоящем Кодексе - исследовательский корпоративный центр), либо участником проекта в соответствии с Федеральным законом от 29 июля 2017 года № 216-ФЗ \"Об инновационных научно-технологических центрах и о внесении изменений в отдельные законодательные акты Российской Федерации\", применяющими освобождение от исполнения обязанностей налогоплательщика налога на добавленную стоимость в соответствии со статьей 1451 настоящего Кодекса, либо участником Военного инновационного технополиса \"Эра\" Министерства обороны Российской Федерации в соответствии с Федеральным законом от 14 июля 2022 года № 253-ФЗ \"О Военном инновационном технополисе \"Эра\" Министерства обороны Российской Федерации и о внесении изменений в отдельные законодательные акты Российской Федерации\", применяющим освобождение от исполнения обязанностей налогоплательщика налога на добавленную стоимость в соответствии со статьей 1452 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 28.12.2016 № 475-ФЗ) (В редакции  федеральных законов от 30.10.2018 № 373-ФЗ, от 23.11.2024 № 399-ФЗ)\n\n9) хотя бы одна из сторон сделки применяет в течение налогового периода инвестиционный налоговый вычет по налогу на прибыль организаций, предусмотренный статьей 2861 настоящего Кодекса. Положения настоящего подпункта не применяются к сделкам, доходы и (или) расходы по которым признаются в соответствии с главой 25 настоящего Кодекса с 1 января 2022 года по 31 декабря 2024 года, вне зависимости от даты заключения соответствующего договора; (Дополнение подпунктом - Федеральный закон от 27.11.2017 № 335-ФЗ) (В редакции Федерального закона от 26.03.2022 № 67-ФЗ)\n\n10) хотя бы одна из сторон сделки является налогоплательщиком налога на дополнительный доход от добычи углеводородного сырья и доходы (расходы) по такой сделке учитываются при определении налоговой базы по налогу на дополнительный доход от добычи углеводородного сырья. (Дополнение подпунктом - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nСделки, предусмотренные пунктом 2 настоящей статьи, признаются контролируемыми, если сумма доходов по таким сделкам между указанными лицами за соответствующий календарный год превышает 1 миллиард рублей. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n(Пункт в редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n1) сторонами которых являются участники одной и той же консолидированной группы налогоплательщиков, образованной в соответствии с настоящим Кодексом (за исключением сделок, предметом которых является добытое полезное ископаемое, признаваемое объектом налогообложения налогом на добычу полезных ископаемых, при добыче которого налогообложение производится по налоговой ставке, установленной в процентах, а также сделок, доходы (расходы) по которым учитываются при определении налоговой базы по налогу на дополнительный доход от добычи углеводородного сырья); (В редакции федеральных законов от 16.11.2011 № 321-ФЗ; от 19.07.2018 № 199-ФЗ)\n\n2) сторонами которых являются лица, удовлетворяющие одновременно следующим требованиям:\n\nуказанные лица зарегистрированы в одном субъекте Российской Федерации;\n\nуказанные лица не имеют обособленных подразделений на территориях других субъектов Российской Федерации, а также за пределами Российской Федерации;\n\nуказанные лица не уплачивают налог на прибыль организаций в бюджеты других субъектов Российской Федерации;\n\nуказанные лица не имеют убытков (включая убытки прошлых периодов, переносимые на будущие налоговые периоды), принимаемых при исчислении налога на прибыль организаций;\n\nотсутствуют обстоятельства для признания совершаемых такими лицами сделок контролируемыми в соответствии с подпунктами 2 - 7 пункта 2 настоящей статьи; (В редакции Федерального закона от 30.09.2013 № 267-ФЗ)\n\n3) сделки между налогоплательщиками, указанными в пункте 1 статьи 2752 настоящего Кодекса, совершаемые ими при осуществлении деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, в отношении одного и того же месторождения (участка недр - до выделения на соответствующем участке недр первого нового морского месторождения углеводородного сырья); (Дополнение подпунктом - Федеральный закон от 30.09.2013 № 268-ФЗ) (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\n4) межбанковские кредиты (депозиты) со сроком до семи календарных дней (включительно); (Дополнение подпунктом - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\n5) в области военно-технического сотрудничества Российской Федерации с иностранными государствами, осуществляемого в соответствии с Федеральным законом от 19 июля 1998 года № 114-ФЗ \"О военно-техническом сотрудничестве Российской Федерации с иностранными государствами\"; (Дополнение подпунктом - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\n6) сделки по предоставлению поручительств (гарантий) в случае, если все стороны такой сделки являются российскими организациями, не являющимися банками; (Дополнение подпунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n7) сделки по предоставлению беспроцентных займов между взаимозависимыми лицами, местом регистрации либо местом жительства всех сторон и выгодоприобретателей по которым является Российская Федерация; (Дополнение подпунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n8) сделки по уступке налогоплательщиком-банком прав (требований) в случае, если такая уступка прав (требований) осуществляется в рамках реализации мероприятий, предусмотренных планом участия Банка России в осуществлении мер по предупреждению банкротства банка, или в случае, если уступка прав (требований) осуществляется в соответствии с порядком, определенным частью 1 статьи 5 Федерального закона от 29 июля 2018 года № 263-ФЗ \"О внесении изменений в отдельные законодательные акты Российской Федерации\"; (Дополнение подпунктом - Федеральный закон от 06.06.2019 № 125-ФЗ)\n\n9) сделки, одной из сторон которых является организация, удовлетворяющая одновременно следующим требованиям:\n\nместом регистрации либо местом налогового резидентства указанной организации является иностранное государство (территория), с которым заключен договор (соглашение, конвенция) об избежании двойного налогообложения, действие которого приостановлено в соответствии с указом Президента Российской Федерации о приостановлении Российской Федерацией действия отдельных положений международных договоров Российской Федерации по вопросам налогообложения;\n\nуказанная организация в соответствии со своим личным законом является экспортно-кредитным агентством и (или) банком;\n\nуказанная организация и иные участники таких сделок не признаются в соответствии со статьей 1051 настоящего Кодекса взаимозависимыми лицами;\n\nотсутствуют обстоятельства для признания таких сделок контролируемыми в соответствии с подпунктами 1 и 2 пункта 1 настоящей статьи;\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n10) сделки, в результате которых у налогоплательщика возникли долговые обязательства, указанные в подпункте 8 пункта 2 статьи 310 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n11) сделки, одной из сторон которых является организация, местом регистрации либо местом налогового резидентства которой является иностранное государство (территория), с которым заключен договор (соглашение, конвенция) об избежании двойного налогообложения, действие которого приостановлено в соответствии с указом Президента Российской Федерации о приостановлении Российской Федерацией действия отдельных положений международных договоров Российской Федерации по вопросам налогообложения, при условии, что договоры (соглашения), на основании которых совершены указанные сделки, заключены до 1 марта 2022 года, порядок определения цен и (или) методик (формул) ценообразования, применяемый в указанных сделках, не изменялся после 1 марта 2022 года и указанные сделки не соответствуют действовавшим по состоянию на 1 марта 2022 года условиям признания сделок контролируемыми сделками в соответствии с пунктами 1 и 3 настоящей статьи. (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n1) нефть и товары, выработанные из нефти;\n\n2) черные металлы;\n\n3) цветные металлы;\n\n4) минеральные удобрения;\n\n5) драгоценные металлы и драгоценные камни.\n\nВ случае совершения сделок между взаимозависимыми лицами или приравненных к ним сделок с участием комиссионера (агента), действующего от своего имени, но по поручению комитента (принципала), для целей настоящей статьи доходы по сделкам между комитентом (принципалом) и лицом, с которым комиссионером (агентом) заключена сделка, учитываются в соответствии с порядком, установленным главой 25 настоящего Кодекса, с применением метода начисления. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n10. По заявлению федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, суд может признать сделку контролируемой при наличии достаточных оснований полагать, что указанная сделка является частью группы однородных сделок, совершенных в целях создания условий, при которых такая сделка не отвечала бы признакам контролируемой сделки, установленным настоящей статьей.\n\n11. Признание сделок контролируемыми производится с учетом положений пункта 13 статьи 1053 настоящего Кодекса.","article_title":"Статья 105.14. Контролируемые сделки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"95ba1bf87e309b8315797292669dad93ff4136c3c21449a73e03e5c0ac0b5344"},{"code_id":"NK_RF","article_number":"105.15","version_date":"2000-07-31","article_text":"1) о деятельности налогоплательщика (лиц), совершившего контролируемую сделку (группу однородных сделок), связанной с этой сделкой:\n\nперечень лиц (с указанием государств и территорий, налоговыми резидентами которых они являются), с которыми совершена контролируемая сделка, описание контролируемой сделки, ее коммерческих и (или) финансовых условий и прочую информацию о сделке;\n\nсведения о функциях лиц, являющихся сторонами сделки, об используемых ими активах, связанных с этой контролируемой сделкой, и о принимаемых ими экономических (коммерческих) рисках, которые налогоплательщик учитывал при ее заключении, с приложением подтверждающих документов;\n\nсведения о доходах и расходах, численности сотру\n\nдников, сумме прибыли (убытка), стоимости основных средств и нематериальных активов иностранного лица (иностранной структуры без образования юридического лица), являющегося стороной контролируемой сделки, за отчетный период, в котором совершена контролируемая сделка, с приложением подтверждающих документов, в том числе финансовой отчетности, если составление финансовой отчетности предусмотрено личным законом указанного лица (иностранной структуры без образования юридического лица) (в случае невозможности представления финансовой отчетности одновременно с документацией она представляется в срок не позднее двенадцати месяцев с даты окончания финансового года, в котором совершена контролируемая сделка). Положения настоящего абзаца применяются в случае, если контролируемая сделка совершена между лицами, признаваемыми взаимозависимыми лицами в соответствии со статьей 1051 настоящего Кодекса;\n\nдокументы, содержащие регистрационные данные иностранного лица (иностранной структуры без образования юридического лица), являющегося стороной контролируемой сделки, и сведения о лицах, выступающих от имени указанного лица (иностранной структуры без образования юридического лица), предоставленные налогоплательщику при заключении контролируемой сделки;\n\n(Подпункт в редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n2) об использованных методах, предусмотренных главой 143 настоящего Кодекса:\n\nанализ коммерческих и (или) финансовых условий контролируемой сделки, осуществленный налогоплательщиком в соответствии со статьей 1055 настоящего Кодекса;\n\nобоснование причин выбора и способа применения метода (комбинации методов), предусмотренного статьей 1057 настоящего Кодекса;\n\nописание корректировок для обеспечения необходимой степени сопоставимости финансовых и (или) коммерческих условий контролируемой сделки и сопоставляемых сделок (организаций);\n\nуказание на источники информации, используемые налогоплательщиком в соответствии со статьей 1056 настоящего Кодекса, в рамках применения метода (комбинации методов), предусмотренного статьей 1057 настоящего Кодекса;\n\nрасчет интервала рыночных цен (интервала рентабельности) по контролируемой сделке в соответствии с методом (комбинацией методов), предусмотренным статьей 1057 настоящего Кодекса, с описанием подхода, используемого для выбора сопоставимых сделок (организаций), и указанием минимального и максимального значений;\n\nсумма полученных доходов (прибыли) и (или) сумма произведенных расходов (понесенных убытков) в результате совершения контролируемой сделки, полученной рентабельности;\n\nсведения об экономической выгоде, получаемой от контролируемой сделки лицом, которым совершена эта сделка, в результате приобретения информации, прав на результаты интеллектуальной деятельности, прав на обозначения, индивидуализирующие предприятие, его продукцию, работы и услуги (фирменное наименование, товарные знаки, знаки обслуживания), и других исключительных прав (при наличии соответствующих обстоятельств);\n\nсведения о прочих факторах, которые оказали влияние на цену (рентабельность), примененную в контролируемой сделке, в том числе сведения о рыночной стратегии лица, совершившего контролируемую сделку, если эта рыночная стратегия оказала влияние на цену (рентабельность), примененную в этой контролируемой сделке (при наличии соответствующих обстоятельств);\n\nсведения о произведенных налогоплательщиком корректировках налоговой базы и сумм налога (убытка) в соответствии с пунктом 6 статьи 1053 настоящего Кодекса (в случае их осуществления);\n\n(Подпункт в редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n3) в случае совершения налогоплательщиком, являющимся участником международной группы компаний, общая сумма дохода (выручки) которой не удовлетворяет условию, предусмотренному подпунктом 3 пункта 6 статьи 10516-3 настоящего Кодекса, контролируемой сделки (группы однородных сделок), одной из сторон и (или) выгодоприобретателем которой является другой участник такой международной группы компаний, местом регистрации, либо местом жительства, либо местом налогового резидентства которого не является Российская Федерация, следующие сведения в дополнение к сведениям, указанным в подпунктах 1 и 2 настоящего пункта:\n\nсведения о структуре органов управления налогоплательщика и идентификационные сведения о лицах, которым подлежит представлению управленческая отчетность, и государствах (территориях), в которых такие лица осуществляют свою основную деятельность;\n\nсведения о деятельности налогоплательщика и его рыночной стратегии, информация о проведенной реструктуризации деятельности налогоплательщика в рамках международной группы компаний (при ее проведении в налоговом периоде совершения сделки или предшествующем налоговом периоде) и передаче (получении) нематериальных активов (в налоговом периоде совершения сделки или предшествующем налоговом периоде), а также пояснения о том, как такая сделка (сделки) повлияла на деятельность налогоплательщика;\n\nсведения об основных конкурентах налогоплательщика;\n\nописание причин, на основании которых сделан вывод о том, что цена, примененная в контролируемой сделке (группе однородных сделок), соответствует рыночной цене;\n\nописание корректировок, производимых для обеспечения сопоставимости условий сделок (при наличии);\n\nкопии существенных соглашений между участниками международной группы компаний, оказывающих влияние на ценообразование в контролируемой сделке (группе однородных сделок);\n\nкопии соглашений о ценообразовании, налоговых разъяснений компетентных органов иностранных государств (территорий), применяемых в сделках между участниками международной группы компаний, которые имеют отношение к анализируемой контролируемой сделке (группе однородных сделок) и в подготовке которых не участвовал федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов;\n\nаудиторское заключение в отношении бухгалтерской (финансовой) отчетности налогоплательщика за последний отчетный период (если налогоплательщик подлежит обязательному аудиту или проводил добровольный аудит).\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2017 № 340-ФЗ)\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, вправе направить налогоплательщику в порядке, предусмотренном пунктами 1, 2 и 5 статьи 93 или пунктом 2 статьи 931 настоящего Кодекса, требование о представлении документации, предусмотренной пунктом 1 настоящей статьи, в отношении сделки (группы однородных сделок). Истребуемая в соответствии с настоящим пунктом документация представляется налогоплательщиком в течение 30 дней со дня получения соответствующего требования. (Дополнение абзацем - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n1) если цены применяются в сделках в соответствии с предписаниями антимонопольных органов в соответствии с пунктом 8 статьи 1053 настоящего Кодекса либо цена является регулируемой и применяется в соответствии со статьей 1054 настоящего Кодекса;\n\n2) при осуществлении налогоплательщиком сделок с лицами, с которыми он не является взаимозависимым, за исключением сделок, приравненных в целях настоящего Кодекса к сделкам между взаимозависимыми лицами в соответствии с подпунктами 1 - 3 пункта 1 статьи 10514 настоящего Кодекса; (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n3) при сделках с ценными бумагами и производными финансовыми инструментами, обращающимися на организованном рынке ценных бумаг (с учетом положений главы 25 настоящего Кодекса); (В редакции Федерального закона  от 03.07.2016 № 242-ФЗ)\n\n4) при осуществлении сделок, в отношении которых в соответствии с главой 146 настоящего Кодекса заключено соглашение о ценообразовании для целей налогообложения.","article_title":"Статья 105.15. Подготовка и представление документации в целях налогового контроля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c49b71785d23fcc0dbe9ecd4db489806702c59bce5e3b52c6645cb16a5695440"},{"code_id":"NK_RF","article_number":"105.16","version_date":"2000-07-31","article_text":"1. Налогоплательщики обязаны уведомлять налоговые органы о совершенных ими в календарном году контролируемых сделках, указанных в статье 10514 настоящего Кодекса.\n\nНалогоплательщики - физические лица вправе представить указанные уведомления на бумажном носителе. (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\nФорма (форматы) уведомления о контролируемых сделках, а также порядок заполнения формы и порядок представления уведомления о контролируемых сделках в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Министерством финансов Российской Федерации. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nВ случае обнаружения неполноты сведений, неточностей либо ошибок в заполнении представленного уведомления о контролируемых сделках налогоплательщик вправе направить уточненное уведомление.\n\nВ случае подачи уточненного уведомления до момента, когда налогоплательщик узнал об установлении налоговым органом факта отражения в уведомлении недостоверных сведений о контролируемых сделках, налогоплательщик освобождается от ответственности, предусмотренной статьей 1294 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\n1) календарный год, за который представляются сведения о совершенных налогоплательщиком контролируемых сделках;\n\n2) предметы сделок;\n\n3) сведения об участниках сделок:\n\nполное наименование организации, а также идентификационный номер налогоплательщика (в случае, если организация состоит на учете в налоговых органах в Российской Федерации);\n\nфамилия, имя, отчество индивидуального предпринимателя и его идентификационный номер налогоплательщика;\n\nфамилия, имя, отчество и гражданство физического лица, не являющегося индивидуальным предпринимателем;\n\n4) сумма полученных доходов и (или) сумма произведенных расходов (понесенных убытков) по контролируемым сделкам с выделением сумм доходов (расходов) по сделкам, цены которых подлежат регулированию;\n\n5) сведения об условиях совершения сделки, а в отношении сделки, предметом которой являются товары, также сведения об условиях и о базисе поставки товаров, дате отгрузки товаров (дате перехода права собственности на товары, дате признания дохода (расхода) по сделке); (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n6) сведения об использованных методах, предусмотренных главой 143 настоящего Кодекса, и источниках информации о сопоставимых сделках; (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n7) в отношении сделок, которые в целях настоящего Кодекса признаются контролируемыми сделками в соответствии с пунктом 1 статьи 10514 настоящего Кодекса и предметом которых являются товары, входящие в состав одной или нескольких товарных групп, указанных в пункте 5 статьи 10514 настоящего Кодекса (за исключением сделок между взаимозависимыми лицами, местом регистрации, местом жительства либо местом налогового резидентства всех сторон и выгодоприобретателей по которым является Российская Федерация), между лицами, признаваемыми взаимозависимыми в соответствии со статьей 1051 настоящего Кодекса, также сведения о сделках последующей реализации и (или) предшествующей покупки товаров, в том числе сведения о конечном покупателе и (или) происхождении товаров, ценах, коммерческих и (или) финансовых условиях таких сделок (далее - сведения о цепочке создания стоимости). (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\nО направлении в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, извещения и соответствующих сведений налоговый орган обязан уведомить налогоплательщика не позднее 10 дней со дня направления извещения. (В редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\nФорма извещения и порядок его направления утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение главой - Федеральный закон от 27.11.2017 № 340-ФЗ)","article_title":"Статья 105.16. Уведомление о контролируемых сделках","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"19ba9c5cf7c5b4d327fcdb77eb5374718d1e959712b7bd8f1309c4248ff13c0f"},{"code_id":"NK_RF","article_number":"105.16-1","version_date":"2000-07-31","article_text":"1. В целях настоящего Кодекса международной группой компаний признается совокупность организаций и (или) иностранных структур без образования юридического лица, связанных между собой посредством участия в капитале и (или) осуществления контроля, для которых соблюдаются все следующие условия:\n\n1) в отношении совокупности организаций и (или) иностранных структур без образования юридического лица, указанной в абзаце первом настоящего пункта, составляется консолидированная финансовая отчетность в соответствии с требованиями законодательства Российской Федерации о бухгалтерском учете либо требованиями фондовых бирж, в том числе иностранных фондовых бирж, при принятии решения о допуске к торгам ценных бумаг любой из указанных организаций и (или) иностранных структур без образования юридического лица или такая отчетность должна была бы составляться, если бы ценные бумаги любой из указанных организаций и (или) иностранных структур без образования юридического лица были допущены к торгам на фондовой бирже, в том числе на иностранной фондовой бирже; (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n2) в состав совокупности организаций и (или) иностранных структур без образования юридического лица, указанной в абзаце первом настоящего пункта, входит хотя бы одна организация (иностранная структура без образования юридического лица), которая признается налоговым резидентом Российской Федерации, либо организация или иностранная структура без образования юридического лица, не признаваемая налоговым резидентом Российской Федерации, которая подлежит налогообложению в отношении предпринимательской деятельности, осуществляемой на территории Российской Федерации через постоянное представительство, и хотя бы одна организация (иностранная структура без образования юридического лица), которая не признается налоговым резидентом Российской Федерации, либо организация или иностранная структура без образования юридического лица, признаваемая налоговым резидентом Российской Федерации, которая подлежит налогообложению в отношении предпринимательской деятельности, осуществляемой на территории иностранного государства (территории) через постоянное представительство.\n\n2. Участником международной группы компаний в целях настоящего Кодекса признаются:\n\n1) лицо, входящее в совокупность организаций и (или) иностранных структур без образования юридического лица, признаваемых международной группой компаний;\n\n2) лицо, относящееся на конец финансового года к организациям и (или) иностранным структурам без образования юридического лица, указанным в пункте 1 настоящей с\n\nтатьи, финансовая отчетность по которому не учитывается при составлении консолидированной финансовой отчетности указанной группы исключительно в силу размера или несущественности данных о таком лице;\n\n3) постоянные представительства лиц, указанных в подпунктах 1 и 2 настоящего пункта.\n\n1) уведомление об участии в международной группе компаний;\n\n2) страновые сведения по международной группе компаний, участником которой является налогоплательщик.\n\n1) глобальная документация по международной группе компаний (далее - глобальная документация);\n\n2) национальная документация участника международной группы компаний (далее - национальная документация);\n\n3) страновой отчет международной группы компаний по государствам (территориям), налоговыми резидентами которых являются участники международной группы компаний (далее - страновой отчет).\n\n1) материнская компания международной группы компаний - участник международной группы компаний, который прямо и (или) косвенно участвует в остальных участниках этой международной группы или иным способом осуществляет контроль над ними и доля участия (наличие контроля) которого является достаточной для того, чтобы финансовая отчетность других участников подлежала включению в консолидированную финансовую отчетность такого участника международной группы компаний либо подлежала бы включению в такую консолидированную финансовую отчетность, если бы ценные бумаги такого участника были бы допущены к торгам на фондовой бирже, в том числе на иностранной фондовой бирже (за исключением случаев, если финансовая отчетность такого участника подлежит включению в консолидированную финансовую отчетность другого участника этой международной группы);\n\n2) уполномоченный участник международной группы компаний - участник международной группы компаний, на которого материнской компанией международной группы компаний возложена обязанность по представлению от имени такой международной группы компаний странового отчета в компетентные органы иностранного государства (территории), налоговым резидентом которого является этот участник либо в котором его деятельность приводит к образованию постоянного представительства;\n\n3) финансовый год - период, за который составляется или должна была бы составляться консолидированная финансовая отчетность международной группы компаний;\n\n4) отчетный период - финансовый год, следующий за финансовым годом, в котором общая сумма дохода (выручки) международной группы компаний в соответствии с консолидированной финансовой отчетностью превышает общую сумму дохода (выручки), указанную в подпункте 3 пункта 6 статьи 10516-3 настоящего Кодекса;\n\n5) консолидированная финансовая отчетность - финансовая отчетность международной группы компаний, составляемая в соответствии с законодательством Российской Федерации, Международными стандартами финансовой отчетности или иными международно признанными стандартами составления финансовой отчетности, принимаемыми фондовыми биржами, в том числе иностранными фондовыми биржами, для принятия решения о допуске ее ценных бумаг к торгам, в которой активы, обязательства, капитал, доход, расходы и денежные потоки материнской компании международной группы компаний и участников международной группы компаний представлены как активы, обязательства, капитал, доход, расходы и денежные потоки единого субъекта экономической деятельности.","article_title":"Статья 105.16-1. Общие положения о документации по международным группам компаний","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0d1729de8a0442928f89eac2797ba47b76d5b58e5fbd6968ff04cd3d6cda22e1"},{"code_id":"NK_RF","article_number":"105.16-2","version_date":"2000-07-31","article_text":"1. Налогоплательщики (за исключением иностранных организаций, получающих только доходы, указанные в статье 309 настоящего Кодекса), являющиеся участниками международной группы компаний, в случаях, порядке и сроки, которые установлены настоящей статьей, представляют в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, уведомления об участии в международной группе компаний.\n\n2. Налогоплательщики, являющиеся участниками международной группы компаний, освобождаются от обязанности представления уведомления об участии в международной группе компаний в следующих случаях:\n\n1) материнская компания международной группы компаний или уполномоченный участник международной группы компаний является российской организацией либо иностранной организацией (иностранной структурой без образования юридического лица), добровольно признавшей себя налоговым резидентом Российской Федерации, представили уведомление об участии в международной группе компаний с отражением информации обо всех участниках этой группы, признаваемых налогоплательщиками в соответствии с настоящим Кодексом (за исключением иностранных организаций, получающих только доходы, указанные в статье 309 настоящего Кодекса);\n\n2) уведомление об участии в международной группе компаний представлено участником международной группы компаний, являющимся российской организацией или иностранной организацией (иностранной структурой без образования юридического лица), добровольно признавшей себя налоговым резидентом Российской Федерации, на которого материнской компанией или уполномоченным участником такой международной группы компаний, не являющимися налоговыми резидентами Российской Федерации, возложена обязанность представить уведомление об участии в международной группе компаний с отражением информации обо всех участниках этой международной группы компаний, признаваемых налогоплательщиками в соответствии с настоящим Кодексом (за исключением иностранных организаций, получающих только доходы, указанные в статье 309 настоящего Кодекса).\n\n3. Освобождение от обязанности, предусмотренное пунктом 2 настоящей статьи, применяется в отношении налогоплательщиков, являющихся участниками международной группы компаний, информация о которых представлена в соответствующем уведомлении об участии в международной группе компаний в установленный срок.\n\n4. Уведомление об участии в международной группе компаний представляется по установленному формату только в электронной форме в срок не позднее восьми месяцев с даты окончания отчетного периода для материнской компании такой международной группы компаний.\n\nФормат уведомления об участии в международной группе компаний, порядок его заполнения и представления в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n5. Уведомление об участии в международной группе компаний должно содержать следующие сведения на дату окончания отчетного периода:\n\n1) наименование, основной государственный регистрационный номер, идентификационный номер каждого налогоплательщика, являющегося участником международной группы компаний, код причины постановки его на учет;\n\n2) информация о том, является ли налогоплательщик, представляющий уведомление, материнской компанией международной группы компаний или уполномоченным участником международной группы компаний;\n\n3) информация о включении (невключении) налогоплательщика, представляющего уведомление, в перечень стратегических предприятий и стратегических акционерных обществ либо о том, является ли налогоплательщик дочерним хозяйственным обществом предприятия или акционерного общества, включенных в такой перечень;\n\n4) информация о федеральном органе исполнительной власти либо государственной корпорации, осуществляющих выдачу предварительного согласия, предусмотренного абзацем вторым пункта 5 статьи 10516-3 настоящего Кодекса; (В редакции Федерального закона от 06.06.2019 № 125-ФЗ)\n\n5) наименование участника, являющегося материнской компанией международной группы компаний, государство (территория) ее налогового резидентства, регистрационный номер (номера), присвоенный материнской компании международной группы компаний в государстве (на территории) ее регистрации (инкорпорации), код (коды) материнской компании международной группы компаний в качестве налогоплательщика в государстве (на территории) ее регистрации (инкорпорации) (или их аналоги), адрес в государстве (на территории) регистрации (инкорпорации) материнской компании международной группы компаний (при наличии);\n\n6) наименование участника, являющегося уполномоченным участником международной группы компаний (при наличии), государство (территория) его налогового резидентства, регистрационный номер (номера), присвоенный уполномоченному участнику международной группы компаний в государстве (на территории) его регистрации (инкорпорации), код (коды) уполномоченного участника международной группы компаний в качестве налогоплательщика в государстве (на территории) его регистрации (инкорпорации) (или их аналоги), адрес в государстве (на территории) регистрации (инкорпорации) уполномоченного участника международной группы компаний (при наличии);\n\n7) основания, подтверждающие право участника международной группы компаний на представление странового отчета и (или) уведомления об участии в международной группе компаний в отношении всех участников этой группы, признаваемых налогоплательщиками в соответствии с настоящим Кодексом (за исключением иностранных организаций, получающих только доходы, указанные в статье 309 настоящего Кодекса);\n\n8) дата, являющаяся последним днем отчетного периода.\n\n6. При обнаружении налогоплательщиком в уведомлении об участии в международной группе компаний неполноты сведений, неточностей либо ошибок в его заполнении налогоплательщик вправе представить уточненное уведомление об участии в международной группе компаний.\n\nВ случае представления указанного уточненного уведомления до момента, когда налогоплательщик узнал об установлении федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, или территориальным налоговым органом факта отражения в уведомлении недостоверных сведений, такой налогоплательщик освобождается от ответственности, предусмотренной статьей 1299 настоящего Кодекса.\n\n7. Положения настоящей статьи не распространяются на налогоплательщиков, являющихся участниками международной группы компаний, общая сумма дохода (выручки) которой удовлетворяет условию, предусмотренному подпунктом 3 пункта 6 статьи 10516-3 настоящего Кодекса.","article_title":"Статья 105.16-2. Представление уведомлений об участии в международной группе компаний","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7da17fbf84aa1ef8c83c3ecd3069558d4e3083de18cc44df873ba82353be73bd"},{"code_id":"NK_RF","article_number":"105.16-3","version_date":"2000-07-31","article_text":"1. Налогоплательщики (за исключением иностранных организаций, получающих только доходы, указанные в статье 309 настоящего Кодекса), являющиеся участниками международной группы компаний, представляют страновые сведения в случаях, порядке и сроки, которые установлены настоящим Кодексом.\n\n2. Страновой отчет представляется материнской компанией международной группы компаний или уполномоченным участником международной группы компаний, если материнская компания международной группы компаний или уполномоченный участник международной группы компаний является российской организацией или иностранной организацией (иностранной структурой без образования юридического лица), добровольно признавшей себя налоговым резидентом Российской Федерации.\n\nСтрановой отчет представляется участником международной группы компаний, который является налогоплательщиком в соответствии с настоящим Кодексом (за исключением иностранных организаций, получающих только доходы, указанные в статье 309 настоящего Кодекса), по требованию федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, за исключением случаев, предусмотренных пунктом 6 настоящей статьи, в срок, установленный федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, который не может составлять менее трех месяцев со дня получения налогоплательщиком указанного требования. (В редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\nСтрановой отчет представляется материнской компанией международной группы компаний или уполномоченным участником международной группы компаний в срок не позднее двенадцати месяцев с даты окончания отчетного периода.\n\n3. Глобальная документация и национальная документация представляются участником международной группы компаний, который является налогоплательщиком в соответствии с настоящим Кодексом (за исключением иностранных организаций, получающих только доходы, указанные в статье 309 настоящего Кодекса).\n\nГлобальная документация представляется по требованию федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, в течение трех месяцев со дня получения такого требования. Глобальная документация может быть истребована у участника международной группы компаний, который является налогоплательщиком в соответствии с настоящим Кодексом (за исключением иностранных организаций, получающих только доходы, указанные в статье 309 настоящего Кодекса), не ранее чем по истечении двенадцати месяцев и не позднее чем по истечении тридцати шести месяцев с даты окончания отчетного периода, указанного в требовании. В случае, если указанное требование направляется в связи с запросом компетентного органа иностранного государства (территории), поступившим в соответствии с настоящим Кодексом и положениями международных договоров Российской Федерации, к нему прилагается копия такого запроса.\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, не вправе истребовать у налогоплательщика, являющегося участником международной группы компаний, глобальную документацию, ранее представленную по требованию федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, иным участником такой международной группы компаний за соответствующий отчетный период. Указанное ограничение не распространяется на случаи, если глобальная документация, представленная налогоплательщиком, была утрачена вследствие обстоятельств непреодолимой силы.\n\nНациональная документация представляется по требованию федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, в порядке и сроки, которые установлены статьями 10515 и 10517 настоящего Кодекса.\n\n4. Страновой отчет представляется по установленному формату только в электронной форме.\n\nФормат странового отчета, порядок его заполнения и представления в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nСтрановые сведения представляются на русском языке с отражением показателей в валюте Российской Федерации, если иное не предусмотрено настоящим пунктом. При этом у налогоплательщика остается право одновременно представить страновые сведения на иностранном языке.\n\nСтрановой отчет в отношении финансового года, в котором материнская компания международной группы компаний, по которой представляются страновые сведения, не признавалась налоговым резидентом Российской Федерации, может быть представлен на иностранном языке.\n\nЗначения стоимостных показателей глобальной документации и странового отчета могут указываться в валюте, в которой материнская компания международной группы компаний составляет консолидированную финансовую отчетность.\n\nЗначения стоимостных показателей контролируемых сделок, в отношении которых составляется национальная документация, могут указываться в валюте, в которой выражены такие сделки.\n\nДля целей исчисления значений стоимостных показателей глобальной документации и странового отчета пересчет валюты отчетности участников международной группы компаний, отличной от валюты отчетности материнской компании международной группы компаний, может осуществляться по правилам составления консолидированной финансовой отчетности материнской компании такой международной группы компаний. Информация об используемом курсе валюты приводится в пояснениях к глобальной документации и страновому отчету.\n\n5. Страновой отчет и глобальная документация, содержащие информацию, составляющую государственную тайну, и (или) информацию, прямо и (или) косвенно свидетельствующую о военно-техническом сотрудничестве с иностранными государствами, осуществляемом в соответствии с Федеральным законом от 19 июля 1998 года № 114-ФЗ \"О военно-техническом сотрудничестве Российской Федерации с иностранными государствами\", представляются в части, не содержащей информации, составляющей государственную тайну, и (или) информации, прямо и (или) косвенно свидетельствующей о военно-техническом сотрудничестве с иностранными государствами.\n\nВ случае, если страновой отчет содержит сведения в отношении участников международной группы компаний, включенных в соответствии с законодательством Российской Федерации в перечень стратегических предприятий и стратегических акционерных обществ, а также в отношении их дочерних хозяйственных обществ, информация, касающаяся деятельности таких участников, подлежит передаче компетентным органам иностранных государств (территорий) в соответствии со статьей 1425 настоящего Кодекса только при условии представления налогоплательщиком, представляющим страновой отчет, в отношении таких участников соответствующего предварительного согласия на передачу такой информации, выданного уполномоченным Правительством Российской Федерации федеральным органом исполнительной власти либо государственной корпорацией, осуществляющей полномочия по осуществлению прав собственника имущества указанных участников. (В редакции Федерального закона от 06.06.2019 № 125-ФЗ)\n\n6. Налогоплательщик, являющийся участником международной группы компаний и представивший (в отношении которого представлено) в соответствии с настоящим Кодексом в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, уведомление об участии в этой группе, вправе не представлять страновой отчет в следующих случаях:\n\n1) налогоплательщик является участником международной группы компаний, материнская компания международной группы компаний или уполномоченный участник международной группы компаний которой представляет страновой отчет в соответствии с пунктом 2 настоящей статьи;\n\n2) налогоплательщик является участником международной группы компаний, материнская компания международной группы компаний или уполномоченный участник международной группы компаний которой признается налоговым резидентом иностранного государства (территории), в отношении которого соблюдаются все следующие условия:\n\nзаконодательством такого государства (территории) установлена обязанность представлять в компет\n\nентные органы страновой отчет, содержащий информацию, аналогичную информации, предусмотренной пунктом 1 статьи 10516-6 настоящего Кодекса;\n\nтакое государство (территория) является участником международного договора Российской Федерации по международному автоматическому обмену страновыми отчетами на конец периода, указанного в абзаце третьем пункта 2 настоящей статьи для представления странового отчета за соответствующий отчетный период;\n\nтакое государство (территория) не включено в перечень государств (территорий), допускающих систематическое неисполнение обязательств по автоматическому обмену страновыми отчетами, утверждаемый федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов;\n\nтакое государство (территория) уведомлено соответствующим участником международной группы компаний об участнике международной группы компаний, на которого возложена обязанность по представлению странового отчета (при наличии в законодательстве такого государства (территории) требования о соответствующем уведомлении);\n\n3) налогоплательщик является участником международной группы компаний, общая сумма дохода (выручки) которой в соответствии с консолидированной финансовой отчетностью за финансовый год, составляющий двенадцать последовательных календарных месяцев, непосредственно предшествующих отчетному периоду, составляет или может составлять (в случае, если бы составлялась консолидированная финансовая отчетность):\n\nменее 50 миллиардов рублей - в случае, если материнская компания международной группы компаний признается налоговым резидентом Российской Федерации;\n\nменее величины общей суммы дохода (выручки), установленной законодательством иностранного государства (территории) для возникновения обязанности представления в компетентный орган такого иностранного государства (территории) странового отчета, содержащего информацию, аналогичную информации, предусмотренной пунктом 1 статьи 10516-6 настоящего Кодекса, - в случае, если материнская компания такой международной группы компаний признается налоговым резидентом соответствующего иностранного государства (территории). В случае, если материнская компания международной группы компаний или уполномоченный участник международной группы компаний составляет консолидированную финансовую отчетность в валюте, отличной от валюты Российской Федерации, соответствие условию величины общей суммы дохода (выручки), указанной в настоящем подпункте, определяется с применением среднего курса валюты при составлении консолидированной финансовой отчетности к рублю Российской Федерации, установленного Центральным банком Российской Федерации, за финансовый год, непосредственно предшествующий отчетному периоду.\n\n7. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, направляет налогоплательщику, являющемуся участником международной группы компаний, указанному в подпункте 2 пункта 6 настоящей статьи, требование о предоставлении странового отчета в срок, установленный федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, который не может составлять менее трех месяцев с даты получения налогоплательщиком указанного требования, в следующих случаях:\n\n1) при наличии у федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, информации, полученной от компетентных органов иностранных государств (территорий), о неисполнении материнской компанией международной группы компаний или уполномоченным участником международной группы компаний обязанности по представлению в компетентный орган странового отчета, установленной законодательством иностранного государства (территории);\n\n2) государство (территория), налоговым резидентом которого является материнская компания международной группы компаний или уполномоченный участник международной группы компаний, включено в перечень государств (территорий), допускающих систематическое неисполнение обязательств по автоматическому обмену страновыми отчетами, утверждаемый федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n8. Государство (территория) включается в перечень государств (территорий), допускающих систематическое неисполнение обязательств по автоматическому обмену страновыми отчетами, в случае неисполнения (приостановления исполнения) компетентным органом такого государства (территории) обязательств, предусмотренных международным договором Российской Федерации по автоматическому обмену страновыми отчетами, или по иным причинам необеспечения автоматического обмена страновыми отчетами с Российской Федерацией.\n\n9. Налогоплательщик, являющийся участником международной группы компаний, у которого обязанность по представлению странового отчета возникла на основании требования федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, направляемого в соответствии с пунктом 7 настоящей статьи, освобождается от ответственности, предусмотренной статьей 12910 настоящего Кодекса, за непредставление странового отчета в срок, установленный пунктом 3 настоящей статьи, в случае представления странового отчета в срок, установленный федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.","article_title":"Статья 105.16-3. Общие положения о представлении страновых сведений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c03f5b0cc3aa2bbd8d244bf3a31c4793bfeb3af884a45c6ff7eaa19e1362ee17"}]$law7d0049$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
